KG42.register("edges-53d200a50737f897174c34a6",{"id":"S-11b541f183d0b041","source":"COMP-42adfdfb6dfa84b0","type":"limits","target":"COMP-5e870d267afec9a0","evidence_class":"S","scientific_acceptance":false,"relation_scope":"original_occurrence_pair_only","internal_to_parent":false,"paper_ids":["08-real_time_prices"],"assertions":[{"id":"08-real_time_prices::v141-c-R003::E::v141-c-R003-E001","paper":"08-real_time_prices","rule_id":"v141-c-R003","rule_ref":"08-real_time_prices::v141-c-R003","record":{"edge_id":"v141-c-R003-E001","source":"bidding.supply","target":"clearing.social_welfare","type":"limits","constraint_ids":["v141-c-R003-C002"],"evidence_ids":["v141-b-g02-ev-21","v141-b-g02-ev-22","v141-b-g02-ev-24","v141-b-g02-ev-25","v141-b-g02-ev-27"]},"evidence_class":"S","provenance_gate":"direct_C_edge_with_constraint_and_source_excerpt","scientific_acceptance":false,"accepted_constraint_ids":["v141-c-R003-C002"],"held_constraint_ids":[],"semantic_review_status":"supported","source":"COMP-42adfdfb6dfa84b0","target":"COMP-5e870d267afec9a0","source_occurrence_id":"08-real_time_prices::v141-c-R003::V::bidding.supply","target_occurrence_id":"08-real_time_prices::v141-c-R003::V::clearing.social_welfare","source_unit_id":"08-real_time_prices::v141-a-M01::bidding.supply","target_unit_id":"08-real_time_prices::v141-a-M01::clearing.social_welfare","omega":{"market_type":"DEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"clearing","context_text":"Future-period feasibility constraints in the multi-period stochastic social-welfare optimization. | Multi-period stochastic social-welfare optimization over the study horizon. | Next-step feasibility constraints in the single-period model and the next-step component of the multi-period model. | Regulating-power deployment within the single-period and multi-period social-welfare optimization models. | Single-period social-welfare optimization for the next time step. | TSO optimization of the EcoGrid EU real-time market alongside the regulating power market.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-ev31","v141-b-g02-ev-16","v141-b-g02-ev-17","v141-b-g02-ev-21","v141-b-g02-ev-22","v141-b-g02-ev-24","v141-b-g02-ev-25","v141-b-g02-ev-27"]},"active":true,"source_signature":"2c66a81dc760f86cf265e94b27988c75849e4513182bd32be6566b94df0546f6","relation_scope":"original_occurrence_pair_only","internal_to_parent":false,"source_science":{"mechanism_id":"v141-a-M01","source_definition":"Offered information and submission conditions in this mechanism: Existing RP market receives regulation offers from large/aggregated participants, with 10 MW minimum bid size and 45-minute deadline; distinct from the complementary bidless market.","target_definition":"Economic objective and its applicability in this mechanism: TSO stochastic balancing optimization posts five-minute prices; small consumers/DERs respond without bids or schedules and without obligations to deliver assumed response.","constraints":[{"constraint_id":"v141-c-R003-C002","kind":"mathematical","role":"core","statement":"Submitted regulating-power quantities cap the up- and down-regulating deployment selected by the social-welfare optimization. Scope: Regulating-power deployment within the single-period and multi-period social-welfare optimization models. Condition: For each modeled generating unit and applicable time step and scenario.","expression":"0 ≤ P^{G,UR}_{(g,1)} ≤ Pbar^{G,UR}_{g}, ∀g  (5)\n0 ≤ P^{G,DR}_{(g,1)} ≤ Pbar^{G,DR}_{g}, ∀g  (6)\n0 ≤ P^{G,UR}_{(g,t,s)} ≤ Pbar^{G,UR}_{g}, ∀g, ∀t = 2,...,N_t, ∀s  (17)\n0 ≤ P^{G,DR}_{(g,t,s)} ≤ Pbar^{G,DR}_{g}, ∀g, ∀t = 2,...,N_t, ∀s  (18)","formalization_origin":"source","template_id":null,"members":["bidding.supply","clearing.social_welfare"],"variable_refs":["v141-c-R003-x-PGUR","v141-c-R003-x-PGDR"],"parameter_refs":["v141-c-R003-theta-PGUR-bar","v141-c-R003-theta-PGDR-bar"],"evidence_ids":["v141-b-g02-ev-21","v141-b-g02-ev-22","v141-b-g02-ev-24","v141-b-g02-ev-25","v141-b-g02-ev-27","v141-b-g02-ev-19","v141-b-g01-ev04"]}],"evidence":[{"evidence_id":"v141-b-g02-ev-21","location":{"location_id":"src-da8e4e26d6-p07-c1r2__v141-a-M01-clearing","page":7,"printed_page":null,"section":"IV-A. Real-Time Price Settlement Model","anchor_text":"q ( ) p g y tim large unit at next time step . Note that this power is equal to the scheduled genera","equation_id":"Eq. (4)","figure_id":null,"table_id":null,"image_ref":"pages/page-07.png","occurrence_role":"formula"},"source_text":"Equation (4) determines the total power generated by each large unit at next time step $(t = 1)$. Note that this power is equal to the scheduled generation in the day-ahead market plus the deployment of regulating power at next time step. Constraints (5) and (6) limit the deployment of up and down regulating power according to the submitted bids. Ramp limits of large generating units are imposed through (7). Equations (8) and (9) determine the response of the ﬂexible demand and distributed energy resources, respectively, to a real-time price variation. Moreover, $\\alpha_{(l,1)}$ and $\\alpha_{(d,1)}$ correspond to the expected value of the response parameter to real-time electricity prices of the consumers and DERs, respectively. The maximum and minimum changes in the power consumed and produced by these prosumers are bounded through constraints (10) and (11). Finally, constraints (12), (13) are positive variable declarations. By solving the above optimization problem using commercial software like GAMS, we can obtain real time price at next time step $(t = 1)$, the response of ﬂexible response and DERs, the deployment of up and down regulating power, and marginal cost of activated up or down regulating power."},{"evidence_id":"v141-b-g02-ev-22","location":{"location_id":"src-da8e4e26d6-p07-c2r2__v141-a-M01-clearing","page":7,"printed_page":null,"section":"IV-B. Real-Time Price Settlement and Forecast Model","anchor_text":"time step and price forecasts at time step is for different possible scenarios. The TSO also de- lus","equation_id":"Eq. (14)","figure_id":null,"table_id":null,"image_ref":"pages/page-07.png","occurrence_role":"formula"},"source_text":"In real life, only a real-time price signal for the next ﬁve minute may not be sufﬁcient for market players for scheduling their production or consumption in an optimal way. Short-term and accurate real-time price forecast (e.g., price forecast for the operational hour) based on the predicted requirements of balancing power can be delivered to market players for optimally adjusting their production or consumption planning. Inspired by that, a multi-period optimization model for determining real-time price and price forecast should also be developed. Uncertain parameters such as wind production and aggregated response of consumers and DERs to real-time electricity prices are approximated by a set of scenarios with their corresponding probabilities of occurrence. The TSO will use the following multi-period stochastic optimization model for determining the real-time price at the next time step $(t = 1)$ and price forecasts at time step $t(\\forall t = 2, \\ldots, N_t)$ for different possible scenarios. The TSO also determines the deployment of up and down regulating power at the next time step $(t = 1)$ and time step $t(\\forall t = 2, \\ldots, N_t)$ for all possible scenarios respectively. The objective function of the proposed model will then be the maximization of the expected social welfare throughout the study horizon, i.e., the minimization of the reserve deployment cost by the generators and DERs for providing balancing power plus wind spillage cost minus the utility losses of the consumers. As shown in (14) at the bottom of the page, the objective function includes two items. The ﬁrst item represents the corresponding cost at next time step $(t = 1)$, which is the same as (4). The second item represents the expected cost incurred from time step $t = 2$ to time step $t = N_t$. The objective function (14) is subject to constraints (2), (4)–(13) and following constraints:"},{"evidence_id":"v141-b-g02-ev-24","location":{"location_id":"src-da8e4e26d6-p07-c2r3__v141-a-M01-clearing","page":7,"printed_page":null,"section":"IV-B. Real-Time Price Settlement and Forecast Model","anchor_text":"ial me (15) he ost ve ng rm the (16) al- lly (17)","equation_id":"Eq. (15)","figure_id":null,"table_id":null,"image_ref":"pages/page-07.png","occurrence_role":"formula"},"source_text":"$P^{G}_{(g,t,s)} = P^{G,D}_{g} + P^{G,UR}_{(g,t,s)} - P^{G,DR}_{(g,t,s)}, \\forall g, \\forall t = 2, \\ldots, N_t, \\forall s$  (15)\n$\\sum_{l}^{N_L} (P^{L}_{(l,t,s)} + \\Delta P^{L}_{(l,t,s)} - L^{Shed}_{(l,t,s)}) - \\sum_{g}^{N_G} P^{G}_{(g,t,s)} - \\sum_{d}^{N_{DER}} (P^{DER}_{(d,t,s)} + \\Delta P^{DER}_{(d,t,s)}) - \\sum_{w}^{N_W} (P^{W}_{(w,t,s)} - W^{Spill}_{(w,t,s)}) = 0, \\forall t = 2, \\ldots, N_t, \\forall s$  (16)\n$0 \\le P^{G,UR}_{(g,t,s)} \\le \\overline{P^{G,UR}_{g}}, \\forall g, \\forall t = 2, \\ldots, N_t, \\forall s$  (17)"},{"evidence_id":"v141-b-g02-ev-25","location":{"location_id":"src-da8e4e26d6-p08-c1r1__v141-a-M01-clearing","page":8,"printed_page":null,"section":"IV-B. Real-Time Price Settlement and Forecast Model","anchor_text":"DING et al.: REAL-TIME MARKET CONCEPT ARCHITECTURE (18) (19) (20) (21) (22)","equation_id":"Eq. (18)","figure_id":null,"table_id":null,"image_ref":"pages/page-08.png","occurrence_role":"formula"},"source_text":"$0 \\le P^{G,DR}_{(g,t,s)} \\le \\overline{P^{G,DR}_{g}}, \\forall g, \\forall t = 2, \\ldots, N_t, \\forall s$  (18)\n$P^{G}_{(g,t-1,s)} - DR_{g} \\le P^{G}_{(g,t,s)} \\le P^{G}_{(g,t-1,s)} + UR_{g}, \\forall g, \\forall t = 2, \\ldots, N_t, \\forall s$  (19)\n$-\\alpha_{(l,t,s)} \\cdot \\Delta P^{L}_{(l,t,s)} = \\lambda^{R}_{(t,s)} - \\lambda^{D}, \\forall l, \\forall t = 2, \\ldots, N_t, \\forall s$  (20)\n$\\alpha_{(d,t,s)} \\cdot \\Delta P^{DER}_{(d,t,s)} = \\lambda^{R}_{(t,s)} - \\lambda^{D}, \\forall d, \\forall t = 2, \\ldots, N_t, \\forall s$  (21)\n$P^{L,min}_{(l,t)} \\le P^{L}_{(l,t)} + \\Delta P^{L}_{(l,t,s)} \\le P^{L,max}_{(l,t)}, \\forall l, \\forall t = 2, \\ldots, N_t, \\forall s$  (22)"},{"evidence_id":"v141-b-g02-ev-27","location":{"location_id":"src-da8e4e26d6-p08-c1r3__v141-a-M01-clearing","page":8,"printed_page":null,"section":"V. Quantitative Analyses","anchor_text":"p y price variations is described through (20) and (21) respectively. Likewise, the maximum and mini","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-08.png","occurrence_role":"unknown"},"source_text":"Equation (15) determines the total power produced by each large generating unit, time period and scenario. The power balance at each time period and scenario is enforced through (16). Constraints (17) and (18) limit the maximum deployment of up and down regulating power at each time period and scenario. The generating unit ramps bound the power generated at each time period and scenario through constraint (19). The response of consumers and DERs to real-time electricity price variations is described through (20) and (21) respectively. Likewise, the maximum and minimum changes of the consumers and DER's are imposed through constraints (22) and (23). Constraints (24) and (25) are positive variable declarations. By solving the above optimization problem, we can obtain real time prices, the response of ﬂexible response and DERs, the deployment of up and down regulating power, and marginal cost of activated up or down regulating power at each time period for different scenarios."},{"evidence_id":"v141-b-g01-ev04","location":{"location_id":"src-da8e4e26d6-p01-c2r2__v141-a-M01-clearing","page":1,"printed_page":null,"section":"NOMENCLATURE","anchor_text":"Number of wind farms op- on- Number of scenarios to Constants ets ow Scheduled generated power of un","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-01.png","occurrence_role":"definition"},"source_text":"Constants: P^{G,D}_{g} Scheduled generated power of unit g in the day-ahead market (MW); \\bar{P}^{G,UR}_{g} Up-regulating power offered by unit g (MW); \\bar{P}^{G,DR}_{g} Down-regulating power offered by unit g (MW); \\lambda^{G,UR}_{g} Bidding cost of electricity for up-regulation of unit g (euros/MWh); \\lambda^{G,DR}_{g} Bidding cost of electricity for down-regulation of unit g (euros/MWh); V^{LOL}_{l} Value of load shed corresponding to load l (euros/MWh); V^{spill}_{w} Value of wind spillage of wind farm w (euros/MWh); UR_{g} Up-ramp of generating unit g (MW/h); DR_{g} Down-ramp of generating unit g (MW/h)."},{"evidence_id":"v141-b-g02-ev-19","location":{"location_id":"src-da8e4e26d6-p06-c2r3__v141-a-M01-clearing","page":6,"printed_page":null,"section":"IV-A. Real-Time Price Settlement Model","anchor_text":"The objective function (3), shown at the bottom of the page, aims to minimize the regulating power c","equation_id":"Eq. (4)","figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"formula"},"source_text":"$P^{G}_{(g,1)} = P^{G,D}_{g} + P^{G,UR}_{(g,1)} - P^{G,DR}_{(g,1)}, \\forall g$  (4)\n$0 \\le P^{G,UR}_{(g,1)} \\le \\overline{P^{G,UR}_{g}}, \\forall g$  (5)\n$0 \\le P^{G,DR}_{(g,1)} \\le \\overline{P^{G,DR}_{g}}, \\forall g$  (6)\n$P^{G}_{(g,0)} - DR_{g} \\le P^{G}_{(g,1)} \\le P^{G}_{(g,0)} + UR_{g}, \\forall g$  (7)"}],"omega":{"market_type":"DEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"clearing","context_text":"Future-period feasibility constraints in the multi-period stochastic social-welfare optimization. | Multi-period stochastic social-welfare optimization over the study horizon. | Next-step feasibility constraints in the single-period model and the next-step component of the multi-period model. | Regulating-power deployment within the single-period and multi-period social-welfare optimization models. | Single-period social-welfare optimization for the next time step. | TSO optimization of the EcoGrid EU real-time market alongside the regulating power market.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-ev31","v141-b-g02-ev-16","v141-b-g02-ev-17","v141-b-g02-ev-21","v141-b-g02-ev-22","v141-b-g02-ev-24","v141-b-g02-ev-25","v141-b-g02-ev-27"]},"source_record":{"edge_id":"v141-c-R003-E001","source":"bidding.supply","target":"clearing.social_welfare","type":"limits","constraint_ids":["v141-c-R003-C002"],"evidence_ids":["v141-b-g02-ev-21","v141-b-g02-ev-22","v141-b-g02-ev-24","v141-b-g02-ev-25","v141-b-g02-ev-27"]},"paper_scope_note":"Single-period and multi-period optimization are kept separate; RP bidders and quote-free responders are kept separate; temporal precedence is not treated as mechanism necessity."}}],"assertion_ids":["08-real_time_prices::v141-c-R003::E::v141-c-R003-E001"]});
